using System;
using System.Collections.Generic;

namespace Astrea;

public class MoonieOmensHandler : ReferenceSingleton<MoonieOmensHandler>
{
	public class DiceInstanceEnhanced
	{
		public DiceInstance DiceInstance;

		public int OriginalActionValue;

		public int OriginalSecondActionValue;

		public DiceInstanceEnhanced(DiceInstance DiceInstance, int OriginalActionValue, int OriginalSecondActionValue)
		{
			this.DiceInstance = DiceInstance;
			this.OriginalActionValue = OriginalActionValue;
			this.OriginalSecondActionValue = OriginalSecondActionValue;
		}
	}

	[NonSerialized]
	public List<Action<List<DiceInstance>>> OnPlayerConvertOmenActions = new List<Action<List<DiceInstance>>>();

	[NonSerialized]
	public List<Action<List<DiceInstanceEnhanced>>> OnPlayerEnhanceOmenActions = new List<Action<List<DiceInstanceEnhanced>>>();

	[NonSerialized]
	public Func<DiceInstance, int> LunarSingularityOmenAction;

	public void ActivateConvertOmens(List<DiceInstance> diceInstances)
	{
		for (int i = 0; i < OnPlayerConvertOmenActions.Count; i++)
		{
			OnPlayerConvertOmenActions[i](diceInstances);
		}
	}

	public void ActivateEnhanceOmens(List<DiceInstanceEnhanced> DiceInstancesEnhanced)
	{
		for (int i = 0; i < OnPlayerEnhanceOmenActions.Count; i++)
		{
			OnPlayerEnhanceOmenActions[i](DiceInstancesEnhanced);
		}
	}

	public int IsLunarSingularityActiveGetMultiplier(DiceInstance diceInstance)
	{
		if (LunarSingularityOmenAction != null)
		{
			return LunarSingularityOmenAction(diceInstance);
		}
		return 1;
	}
}
